after.tests/test_timesheet.py:
# owner: platform

import unittest

from hourglass.timesheet import timesheet_lines
from hourglass.models import Shift, Span
from hourglass.errors import ProjectError

def shift(worker, start, end):
    return Shift(worker, "mon", Span(start, end))

def sample_shifts():
    return [
        shift("Odell", 540, 720),
        shift("Odell", 780, 870),
        shift("Brisa", 480, 1020),
        shift("Quill", 540, 600)
    ]

class TimesheetTests(unittest.TestCase):
    def test_busiest_first_with_hours(self):
        expected = [
            "Brisa: 1 shift, 9.0 hours",
            "Odell: 2 shifts, 4.5 hours",
            "Quill: 1 shift, 1.0 hours"
        ]
        lines = timesheet_lines(sample_shifts())
        self.assertEqual(lines, expected)

    def test_ties_sorted_by_name(self):
        shifts = [shift(n, 0, 60) for n in ("Quill", "Ann")]
        expected = [
            "Ann: 1 shift, 1.0 hours",
            "Quill: 1 shift, 1.0 hours"
        ]
        self.assertEqual(timesheet_lines(shifts), expected)

    def test_hours_one_decimal(self):
        lines = timesheet_lines([shift("Brisa", 600, 620)])
        expected = "Brisa: 1 shift, 0.3 hours"
        self.assertEqual(lines, [expected])

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            timesheet_lines([])

    def test_blank_worker_raises(self):
        for name in ("", "   "):
            with self.assertRaises(ProjectError):
                timesheet_lines([shift(name, 540, 600)])
